-- Registers 6 exams (2025 공통수학2 2학기 기말) and links 130 hand-solution images.
-- A problem that already has a video keeps it: only the image (and an empty title) is filled in.
with wanted(school_name, question_count, display_name) as (
  values
    ('남목고', 20, '2025 남목고 공통수학2 2학기 기말'),
    ('성광여고', 22, '2025 성광여고 공통수학2 2학기 기말'),
    ('신선여고', 21, '2025 신선여고 공통수학2 2학기 기말'),
    ('신정고', 22, '2025 신정고 공통수학2 2학기 기말'),
    ('호계고', 23, '2025 호계고 공통수학2 2학기 기말'),
    ('화봉고', 22, '2025 화봉고 공통수학2 2학기 기말')
),
created as (
  insert into public.school_exam_master
    (exam_year, school_name, subject, exam_type, question_count, scope, display_name, is_active, created_at)
  select 2025, wanted.school_name, '공통수학2', '2학기 기말', wanted.question_count, '고1 2학기 기말', wanted.display_name, true, now()
  from wanted
  where not exists (
    select 1 from public.school_exam_master existing
    where existing.exam_year = 2025 and existing.school_name = wanted.school_name
      and existing.subject = '공통수학2' and existing.exam_type = '2학기 기말'
  )
  returning id, school_name
),
exam as (
  select id, school_name from created
  union all
  select existing.id, existing.school_name from public.school_exam_master existing
  join wanted on wanted.school_name = existing.school_name
  where existing.exam_year = 2025 and existing.subject = '공통수학2' and existing.exam_type = '2학기 기말'
),
